const $=s=>document.querySelector(s);const now=()=>Math.floor(Date.now()/1000);const uid=()=>crypto.randomUUID();
const state={tab:'expenses',expenses:[],categories:[],recurring:[],suggestions:[],prefs:{currency:'USD',timezone:'Local',date_format:'2006-01-02'},next:null,status:navigator.onLine?'Synced':'Offline',errors:0,msg:''};
const money=c=>new Intl.NumberFormat(undefined,{style:'currency',currency:state.prefs.currency||'USD'}).format((c||0)/100);const day=t=>new Date(t*1000).toLocaleDateString();
async function api(url,opt={}){const res=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});if(res.status===401){state.tab='settings';state.msg='Paste your secret again.';render();throw new Error('unauthorized')}if(!res.ok)throw new Error((await res.json().catch(()=>({error:res.statusText}))).error||res.statusText);return res.status===204?null:res.json()}
function openDB(){return new Promise((ok,fail)=>{const r=indexedDB.open('expenses-pwa',1);r.onupgradeneeded=()=>r.result.createObjectStore('outbox',{keyPath:'id'});r.onsuccess=()=>ok(r.result);r.onerror=()=>fail(r.error)})}
async function tx(mode,fn){const db=await openDB();return new Promise((ok,fail)=>{const t=db.transaction('outbox',mode);const s=t.objectStore('outbox');const v=fn(s);t.oncomplete=()=>ok(v);t.onerror=()=>fail(t.error)})}
async function allOutbox(){return tx('readonly',s=>{const r=s.getAll();return new Promise(ok=>r.onsuccess=()=>ok(r.result))})}
async function queue(method,url,body,target){await tx('readwrite',s=>s.put({id:uid(),method,url,body,target_key:target,status:'queued',attempts:0,created_at:Date.now()}));await countErrors();}
async function drain(){if(!navigator.onLine)return;const rows=await allOutbox();for(const r of rows.filter(x=>x.status!=='failed').sort((a,b)=>a.created_at-b.created_at)){try{await api(r.url,{method:r.method,body:JSON.stringify(r.body)});await tx('readwrite',s=>s.delete(r.id))}catch(e){if(/unauthorized/.test(e.message))return;if(e.message){r.status='failed';r.last_error=e.message;await tx('readwrite',s=>s.put(r))}}}await refresh()}
async function write(method,url,body,target){body.client_updated_at=now();try{return await api(url,{method,body:JSON.stringify(body)})}catch(e){if(!navigator.onLine||e.message==='Failed to fetch'){await queue(method,url,body,target);state.status='Offline';render();return body}throw e}}
async function refresh(){try{state.prefs=await api('/api/preferences');state.categories=(await api('/api/categories')).categories||[];state.expenses=(await api('/api/expenses')).expenses||[];state.recurring=(await api('/api/recurring-expenses')).recurring_expenses||[];state.suggestions=(await api('/api/wallet-suggestions?status=pending')).wallet_suggestions||[];state.status=navigator.onLine?'Synced':'Offline';state.msg=''}catch(e){state.status=navigator.onLine?'Sync errors':'Offline';state.msg=e.message}await countErrors();render()}
async function countErrors(){state.errors=(await allOutbox()).filter(r=>r.status==='failed').length}
function nav(){return ['expenses','add','categories','recurring','review','settings'].map(t=>`<button class="${state.tab===t?'active':''}" onclick="go('${t}')">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}
function shell(body){let cls=!navigator.onLine?'offline':state.errors?'err':'';$('#app').innerHTML=`<div class="app"><div class="top"><div class="bar"><h1>Expenses</h1><span class="pill ${cls}">${state.errors?'Sync errors ('+state.errors+')':state.status}</span></div><div class="tabs">${nav()}</div></div>${state.msg?`<p class="error">${state.msg}</p>`:''}${body}</div>`}
window.go=t=>{state.tab=t;render()};
function expenseForm(e={amount:0,currency:state.prefs.currency||'USD',date:now(),merchant:'',description:'',category_id:state.categories[0]?.id||''},suggestion){return `<form onsubmit="saveExpense(event,'${e.id||''}','${suggestion||''}')"><div class="grid"><div><label>Amount</label><input name="amount" type="number" step="0.01" value="${(e.amount||0)/100}" required></div><div><label>Currency</label><input name="currency" value="${e.currency||state.prefs.currency||'USD'}"></div></div><label>Merchant</label><input name="merchant" value="${e.merchant||''}"><label>Category</label><select name="category_id">${state.categories.map(c=>`<option value="${c.id}" ${c.id===e.category_id?'selected':''}>${c.icon||''} ${c.name}</option>`)}</select><label>Description</label><textarea name="description">${e.description||''}</textarea><label>Date</label><input name="date" type="date" value="${new Date((e.date||now())*1000).toISOString().slice(0,10)}"><div class="actions"><button class="btn primary">Save</button></div></form>`}
window.saveExpense=async(ev,id,sid)=>{ev.preventDefault();const f=new FormData(ev.target);const body={id:id||uid(),amount:Math.round(Number(f.get('amount'))*100),currency:f.get('currency'),category_id:f.get('category_id'),merchant:f.get('merchant'),description:f.get('description'),date:Math.floor(new Date(f.get('date')).getTime()/1000)};try{if(sid)await write('POST',`/api/wallet-suggestions/${sid}/confirm`,body,'suggestion:'+sid);else await write(id?'PUT':'POST',id?`/api/expenses/${id}`:'/api/expenses',body,'expense:'+body.id);state.tab='expenses';await refresh()}catch(e){state.msg=e.message;render()}};
window.delExpense=async id=>{if(confirm('Delete expense?')){await write('DELETE','/api/expenses/'+id,{},'expense:'+id);await refresh()}};
function renderExpenses(){shell(`<h2>Feed</h2>${state.expenses.length?'':'<p class="empty">No recent expenses.</p>'}<div class="list">${state.expenses.map(e=>`<div class="card"><div class="row"><div><b>${e.merchant||e.description||'Expense'}</b><div class="muted">${day(e.date)} · ${cat(e.category_id)}</div></div><div class="amount">${money(e.amount)}</div></div><div class="actions"><button class="btn" onclick="editExpense('${e.id}')">Edit</button><button class="btn danger" onclick="delExpense('${e.id}')">Delete</button></div></div>`).join('')}</div>`) }
const cat=id=>state.categories.find(c=>c.id===id)?.name||'';window.editExpense=id=>{state.tab='edit:'+id;render()};
function renderCats(){shell(`<h2>Categories</h2><form onsubmit="saveCat(event)"><div class="grid"><input name="icon" placeholder="Icon"><input name="name" placeholder="Name" required><input name="budget" type="number" step="0.01" placeholder="Budget"></div><button class="btn primary">Add</button></form>${state.categories.map(c=>`<div class="card row"><span>${c.icon||''} <b>${c.name}</b> ${c.budget?'<span class="muted">budget '+money(c.budget)+'</span>':''}</span><button class="btn danger" onclick="delCat('${c.id}')">Delete</button></div>`).join('')}`)}
window.saveCat=async ev=>{ev.preventDefault();const f=new FormData(ev.target);await write('POST','/api/categories',{name:f.get('name'),icon:f.get('icon'),budget:f.get('budget')?Math.round(Number(f.get('budget'))*100):null},'category:'+uid());await refresh()};window.delCat=async id=>{await write('DELETE','/api/categories/'+id,{},'category:'+id);await refresh()};
function renderRecurring(){shell(`<h2>Recurring</h2><form onsubmit="saveRec(event)">${expenseFormFields()}<label>Frequency</label><select name="frequency"><option>monthly</option><option>weekly</option><option>yearly</option></select><button class="btn primary">Add recurring</button></form>${state.recurring.map(r=>`<div class="card row"><span><b>${r.merchant||r.description}</b><br><span class="muted">${r.frequency} · ${money(r.amount)}</span></span><button class="btn danger" onclick="delRec('${r.id}')">Delete</button></div>`).join('')}`)}
function expenseFormFields(){return `<div class="grid"><input name="amount" type="number" step="0.01" placeholder="Amount" required><input name="currency" value="${state.prefs.currency||'USD'}"></div><input name="merchant" placeholder="Merchant"><select name="category_id">${state.categories.map(c=>`<option value="${c.id}">${c.name}</option>`)}</select><input name="description" placeholder="Description">`}
window.saveRec=async ev=>{ev.preventDefault();const f=new FormData(ev.target);await write('POST','/api/recurring-expenses',{amount:Math.round(Number(f.get('amount'))*100),currency:f.get('currency'),category_id:f.get('category_id'),merchant:f.get('merchant'),description:f.get('description'),frequency:f.get('frequency'),start_date:now()},'recurring:'+uid());await refresh()};window.delRec=async id=>{await write('DELETE','/api/recurring-expenses/'+id,{},'recurring:'+id);await refresh()};
function renderReview(){shell(`<h2>Wallet review</h2>${state.suggestions.length?'':'<p class="empty">No pending suggestions.</p>'}${state.suggestions.map(s=>`<div class="card"><div class="row"><div><b>${s.merchant||'Wallet transaction'}</b><div class="muted">${day(s.captured_at)} ${s.card_name||''}</div></div><div class="amount">${s.amount==null?'':money(s.amount)}</div></div>${expenseForm({amount:s.amount||0,currency:s.currency||state.prefs.currency,date:s.captured_at,merchant:s.merchant,description:'',category_id:state.categories[0]?.id},s.id)}<button class="btn danger" onclick="dismiss('${s.id}')">Dismiss</button></div>`).join('')}`)}window.dismiss=async id=>{await write('POST',`/api/wallet-suggestions/${id}/dismiss`,{},'suggestion:'+id);await refresh()};
function renderSettings(){shell(`<h2>Settings</h2><form onsubmit="exchange(event)"><label>Sync secret</label><input name="secret" type="password" autocomplete="current-password"><button class="btn primary">Save browser cookie</button></form><form onsubmit="savePrefs(event)"><label>Currency</label><input name="currency" value="${state.prefs.currency||''}"><label>Timezone</label><input name="timezone" value="${state.prefs.timezone||''}"><label>Date format</label><input name="date_format" value="${state.prefs.date_format||''}"><button class="btn primary">Save preferences</button></form><h2>Sync errors</h2><div id="errs"></div>`) ; renderErrs()}
window.exchange=async ev=>{ev.preventDefault();try{await api('/api/auth/exchange',{method:'POST',headers:{Authorization:'Bearer '+new FormData(ev.target).get('secret')}});state.msg='Secret saved.';await refresh()}catch(e){state.msg=e.message;render()}};window.savePrefs=async ev=>{ev.preventDefault();const f=new FormData(ev.target);await api('/api/preferences',{method:'PUT',body:JSON.stringify({currency:f.get('currency'),timezone:f.get('timezone'),date_format:f.get('date_format')})});await refresh()};
async function renderErrs(){const el=$('#errs');if(!el)return;const rows=(await allOutbox()).filter(r=>r.status==='failed');el.innerHTML=rows.length?rows.map(r=>`<div class="card"><b>${r.method} ${r.url}</b><p class="muted small">${r.last_error}</p><button class="btn" onclick="retry('${r.id}')">Retry</button><button class="btn danger" onclick="discard('${r.id}')">Discard</button></div>`).join(''):'<p class="empty">No failed writes.</p>'}window.retry=async id=>{await tx('readwrite',s=>{const g=s.get(id);g.onsuccess=()=>{const r=g.result;r.status='queued';s.put(r)}});await drain()};window.discard=async id=>{await tx('readwrite',s=>s.delete(id));await countErrors();render()};
function render(){if(state.tab==='expenses')return renderExpenses();if(state.tab==='add')return shell('<h2>Add expense</h2>'+expenseForm());if(state.tab.startsWith('edit:'))return shell('<h2>Edit expense</h2>'+expenseForm(state.expenses.find(e=>e.id===state.tab.slice(5))));if(state.tab==='categories')return renderCats();if(state.tab==='recurring')return renderRecurring();if(state.tab==='review')return renderReview();return renderSettings()}
if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js');addEventListener('online',()=>{state.status='Syncing';drain()});addEventListener('focus',drain);document.addEventListener('visibilitychange',()=>{if(!document.hidden)drain()});refresh().then(drain);
if(/iphone|ipad|ipod/i.test(navigator.userAgent)&&!matchMedia('(display-mode: standalone)').matches&&!localStorage.installHint){setTimeout(()=>{$('#app').insertAdjacentHTML('beforeend','<div class="sheet install"><b>Add to Home Screen</b><p>Open Share in Safari, then choose Add to Home Screen.</p><button class="btn" onclick="localStorage.installHint=1;this.parentElement.remove()">Got it</button></div>')},500)}
